paragraph.math:
$$\begin{array}{l}
  {{Area\ of}R = {\text{Area of the region under the graph of}f(x) - {Area\ of\ the\ region\ under\ the\ graph\ of}g(x)}} \\
  {\phantom{{Area\ of}R} = {\int_{a}^{b}{f(x)\mathit{dx} - {\int_{a}^{b}{g(x)\mathit{dx}}}}}} \\
  {\phantom{{Area\ of}R} = {\int_{a}^{b}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{1}^{2}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}} = {\int_{1}^{2}{\lbrack{({2x - 1})} - {({x^{2} - 4})}\rbrack}\mathit{dx}}} \\
  {\phantom{\int_{1}^{2}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}} = {\int_{1}^{2}{({- x^{2} + 2x + 3})\mathit{dx}}}} \\
  {\phantom{\int_{1}^{2}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}} = \left. - \frac{1}{3}x^{3} + x^{2} + 3x \right|_{1}^{2}} \\
  {\phantom{\int_{1}^{2}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}} = \left( {- \frac{8}{3} + 4 + 6} \right) - \left( {- \frac{1}{3} + 1 + 3} \right) = \frac{11}{3}}
  \end{array}$$
